curl /public/api/v1/agents/runs \
  --request POST \
  --header 'Content-Type: application/json' \
  --data '{
  "system_prompt": "Find the CEO, founders, and directors of the company by domain.",
  "input_schema": {
    "properties": {
      "domain": {
        "type": "string"
      }
    },
    "required": [
      "domain"
    ],
    "type": "object"
  },
  "output_schema": {
    "properties": {
      "name": {
        "type": "string"
      }
    },
    "required": [
      "name"
    ],
    "type": "object"
  },
  "input_data": {
    "domain": "stripe.com"
  }
}'
